syntax:
template <class InputIterator>
typename iterator_traits<InputIterator>::difference_type
distance(InputIterator first, InputIterator last);

code_example:
#include <vector>
#include <list>
#include <iterator>
#include <iostream>

template <class InputIterator>
typename std::iterator_traits<InputIterator>::difference_type
distance(InputIterator first, InputIterator last) {
    return last - first;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5};
    std::list<int> lst = {1, 2, 3, 4, 5};

    auto vec_dist = distance(vec.begin(), vec.end());
    // Note: For std::list, operator- is not defined; this is for illustration.
    std::cout << "Vector distance: " << vec_dist << std::endl;

    // For list, use std::distance from <iterator>:
    auto list_dist = std::distance(lst.begin(), lst.end());
    std::cout << "List distance: " << list_dist << std::endl;
    return 0;
}
